import org.junit.jupiter.api.Test;
import org.locationtech.spatial4j.context.SpatialContext;
import org.locationtech.spatial4j.io.GeohashUtils;
import org.locationtech.spatial4j.shape.Point;

import co.elastic.clients.elasticsearch.core.search.Hit;

class ElasticsearchGeometryCompatibilityTest {
	private static final IRI SUBJECT = Values.iri("urn:subject");
	private static final IRI LOCATION = Values.iri("urn:location");

	@Test
	void configuredGeometryPredicatesKeepOrdinaryTextInTheSearchableField() throws IOException {
		var index = new RecordingIndex();
		var vf = SimpleValueFactory.getInstance();
		var label = vf.createStatement(SUBJECT, LOCATION, Values.literal("main entrance"));
		var point = vf.createStatement(SUBJECT, LOCATION, Values.literal("POINT(0 0)", CoreDatatype.GEO.WKT_LITERAL));

		index.addStatement(label);
		var document = index.getDocument(SUBJECT, null);
		assertNotNull(document);
		assertEquals(List.of("main entrance"), document.getProperty(LOCATION.stringValue()));

		index.addRemoveStatements(List.of(point), List.of());
		var updated = (ElasticsearchDocument) index.getDocument(SUBJECT, null);
		assertEquals(Set.of("main entrance", "POINT(0 0)"),
				Set.copyOf(updated.getProperty(LOCATION.stringValue())));
		assertNotNull(updated.getSource().get(ElasticsearchIndex.toGeoPointFieldName(LOCATION.stringValue())));

		index.addRemoveStatements(List.of(), List.of(label));
		assertEquals(List.of("POINT(0 0)"), index.getDocument(SUBJECT, null).getProperty(LOCATION.stringValue()));
	}

	@Test
	void legacyGeohashDistanceBindingUsesTheBackendDistance() {
		var index = new RecordingIndex();
		String field = LOCATION.stringValue();
		String pointField = ElasticsearchIndex.toGeoPointFieldName(field);
		var point = Values.literal("POINT(0.001 0)", CoreDatatype.GEO.WKT_LITERAL);
		var hit = Hit.<Map<String, Object>>of(h -> h.id("1")
				.index("idx")
				.source(Map.of(
						SearchFields.URI_FIELD_NAME, SUBJECT.stringValue(),
						ElasticsearchIndex.toPropertyFieldName(field), point.getLabel(),
						pointField, GeohashUtils.encodeLatLon(0, 0.001, 7))));
		index.distanceHit = new ElasticsearchDocumentDistance(hit, ignored -> SpatialContext.GEO, pointField,
				GEOF.UOM_METRE, 0, 0);
		var origin = Values.literal("POINT(0 0)", CoreDatatype.GEO.WKT_LITERAL);
		// The legacy geo field holds a geohash center within 110 m. The original WKT is about 111.2 m away.
		var query = new DistanceQuerySpec(origin, GEOF.UOM_METRE, 110, "distance", LOCATION, "wkt", "s", null);

		var rows = index.evaluate(query);
		assertEquals(1, rows.size());
		var row = rows.iterator().next();
		assertEquals(point, row.getValue("wkt"));
		assertEquals(Values.literal(index.distanceHit.getDistance()), row.getValue("distance"));
	}

	private static final class RecordingIndex extends ElasticsearchIndex {
		private final Map<String, SearchDocument> documents = new HashMap<>();
		private DocumentDistance distanceHit;

		private RecordingIndex() {
			wktFields = Set.of(LOCATION.stringValue());
			defaultNumDocs = 1;
			maxDocs = 1;
		}

		@Override
		protected SearchDocument getDocument(String id) {
			return documents.get(id);
		}

		@Override
		protected Iterable<? extends SearchDocument> getDocuments(String resourceId) {
			return documents.values().stream().filter(doc -> resourceId.equals(doc.getResource())).toList();
		}

		@Override
		protected SearchDocument newDocument(String id, String resourceId, String context) {
			return new ElasticsearchDocument(id, DEFAULT_DOCUMENT_TYPE, DEFAULT_INDEX_NAME, resourceId, context,
					ignored -> SpatialContext.GEO);
		}

		@Override
		protected void addDocument(SearchDocument doc) {
			documents.put(doc.getId(), doc);
		}

		@Override
		protected void updateDocument(SearchDocument doc) {
			addDocument(doc);
		}

		@Override
		protected BulkUpdater newBulkUpdate() {
			return new SimpleBulkUpdater(this);
		}

		@Override
		protected SpatialContext getSpatialContext(String property) {
			return SpatialContext.GEO;
		}

		@Override
		protected Iterable<? extends DocumentDistance> geoQuery(IRI property, Point origin, IRI units, double distance,
				String distanceVar, Var context) {
			return List.of(distanceHit);
		}
	}
}
